// ChatServiceServer is the server API for ChatService service.
// All implementations must embed UnimplementedChatServiceServer
// for forward compatibility.
//
// ChatService exposes all chat, conversation, message, canvas, folder,
// context-management, and attachment operations for the Elitea chat domain.
//
// URL base for elitea_core endpoints:  /api/v2/elitea_core
// URL base for context_manager endpoints: /api/v2/context_manager
//
// All project-scoped routes use the prompt_lib mode segment:
//
//	/api/v2/elitea_core/{resource}/prompt_lib/{project_id}[/{id}...]
//
// URL conflicts resolved by merging:
//   - GET  /conversation/{project_id}/{id}        → GetConversation
//     (was: getRunHistoryDetails + conversationDetails — same URL, same method)
//   - PUT  /conversation/{project_id}/{id}        → UpdateConversation (oneof body/is_hidden)
//     (was: conversationEdit + deleteRunHistoryItem — same URL, same method)
//   - DELETE /task/{project_id}/{task_id}         → StopTask
//     (was: stopLlmTask + stopChatTask — same URL template, parameter name differed)
//   - GET  /folder/{project_id}                   → ListFolders
//     (was: foldersList + folderConversations + dateGroupConversations — same URL, query params selected behaviour)
//
// POST /predict_llm/{project_id} is intentionally kept as two separate RPCs
// (streaming vs unary); the gateway must route by inspecting whether `sid` is
// present in the request body.
type ChatServiceServer interface {
	// GetChatConfig returns model defaults and chat configuration for a project.
	// GET /api/v2/elitea_core/chat_config/prompt_lib/{project_id}
	GetChatConfig(context.Context, *GetChatConfigRequest) (*GetChatConfigResponse, error)
	// GenerateContentStreaming sends a prompt to the LLM and streams back the
	// response as server-sent events.  Identified by the presence of `sid` in
	// the request body.
	// POST /api/v2/elitea_core/predict_llm/prompt_lib/{project_id}
	// Note: the gateway route uses a /stream suffix to disambiguate from the
	// blocking variant; both originally shared the same Python URL and are
	// differentiated at the backend by the `sid` field in the request body.
	GenerateContentStreaming(*GenerateContentStreamingRequest, grpc.ServerStreamingServer[GenerateContentStreamingResponse]) error
	// GenerateContentBlocking sends a prompt to the LLM and waits for the full
	// response before returning.  Used when `sid` is absent.
	// POST /api/v2/elitea_core/predict_llm/prompt_lib/{project_id}
	GenerateContentBlocking(context.Context, *GenerateContentBlockingRequest) (*GenerateContentBlockingResponse, error)
	// StopTask cancels an in-flight prediction or chat task.
	// Merges stopLlmTask (task_id) and stopChatTask (message_group_uuid) —
	// both map to the same DELETE URL template.
	// DELETE /api/v2/elitea_core/task/prompt_lib/{project_id}/{task_id}
	StopTask(context.Context, *StopTaskRequest) (*StopTaskResponse, error)
	// GetRunHistoryList returns a paginated list of run-history conversations.
	// GET /api/v2/elitea_core/conversations/prompt_lib/{project_id}
	GetRunHistoryList(context.Context, *GetRunHistoryListRequest) (*GetRunHistoryListResponse, error)
	// ConversationCreate creates a new conversation thread.
	// POST /api/v2/elitea_core/conversations/prompt_lib/{project_id}
	ConversationCreate(context.Context, *ConversationCreateRequest) (*ConversationCreateResponse, error)
	// GetConversation returns details for a single conversation.
	// Merges getRunHistoryDetails and conversationDetails (same URL).
	// Optional query parameters (messages_offset, messages_limit, sort_order)
	// are used when called as conversationDetails.
	// GET /api/v2/elitea_core/conversation/prompt_lib/{project_id}/{id}
	GetConversation(context.Context, *GetConversationRequest) (*GetConversationResponse, error)
	// UpdateConversation updates an existing conversation.
	// Merges conversationEdit (body field) and deleteRunHistoryItem (is_hidden
	// field) — both are PUT to the same URL.  The `update` oneof selects which
	// operation the caller intends.
	// PUT /api/v2/elitea_core/conversation/prompt_lib/{project_id}/{id}
	UpdateConversation(context.Context, *UpdateConversationRequest) (*UpdateConversationResponse, error)
	// DeleteConversation permanently removes a conversation.
	// DELETE /api/v2/elitea_core/conversation/prompt_lib/{project_id}/{id}
	DeleteConversation(context.Context, *DeleteConversationRequest) (*DeleteConversationResponse, error)
	// SelectConversation marks a conversation as the active selection.
	// POST /api/v2/elitea_core/select_conversation/prompt_lib/{project_id}/{conversation_id}
	SelectConversation(context.Context, *SelectConversationRequest) (*SelectConversationResponse, error)
	// UnselectConversation clears the active conversation selection for a project.
	// DELETE /api/v2/elitea_core/select_conversation/prompt_lib/{project_id}
	UnselectConversation(context.Context, *UnselectConversationRequest) (*UnselectConversationResponse, error)
	// Regenerate re-runs the LLM for a specific conversation turn.
	// POST /api/v2/elitea_core/regenerate/prompt_lib/{project_id}/{id}
	Regenerate(context.Context, *RegenerateRequest) (*RegenerateResponse, error)
	// MessageList returns a paginated list of messages within a conversation.
	// GET /api/v2/elitea_core/messages/prompt_lib/{project_id}/{conversation_id}
	MessageList(context.Context, *MessageListRequest) (*MessageListResponse, error)
	// DeleteMessage removes a single message from a conversation.
	// DELETE /api/v2/elitea_core/message/prompt_lib/{project_id}/{id}
	DeleteMessage(context.Context, *DeleteMessageRequest) (*DeleteMessageResponse, error)
	// DeleteAllMessages removes all messages from a conversation.
	// DELETE /api/v2/elitea_core/messages/prompt_lib/{project_id}/{conversation_id}
	DeleteAllMessages(context.Context, *DeleteAllMessagesRequest) (*DeleteAllMessagesResponse, error)
	// AddParticipant adds one or more participants to a conversation.
	// POST /api/v2/elitea_core/participants/prompt_lib/{project_id}/{id}
	AddParticipant(context.Context, *AddParticipantRequest) (*AddParticipantResponse, error)
	// DeleteParticipant removes a participant from a conversation.
	// DELETE /api/v2/elitea_core/participant/prompt_lib/{project_id}/{conversation_id}/{id}
	DeleteParticipant(context.Context, *DeleteParticipantRequest) (*DeleteParticipantResponse, error)
	// UpdateParticipantSettings updates the settings for a specific participant.
	// PUT /api/v2/elitea_core/entity_settings/prompt_lib/{project_id}/{conversation_id}/{participant_id}
	UpdateParticipantSettings(context.Context, *UpdateParticipantSettingsRequest) (*UpdateParticipantSettingsResponse, error)
	// UpdateParticipantLlmSettings patches LLM model settings for all
	// participants in a conversation.
	// PATCH /api/v2/elitea_core/entity_settings/prompt_lib/{project_id}/{conversation_id}
	UpdateParticipantLlmSettings(context.Context, *UpdateParticipantLlmSettingsRequest) (*UpdateParticipantLlmSettingsResponse, error)
	// CreateCanvas creates a new canvas with associated conversation threads.
	// POST /api/v2/elitea_core/canvases/prompt_lib/{project_id}
	CreateCanvas(context.Context, *CreateCanvasRequest) (*CreateCanvasResponse, error)
	// GetCanvas returns details for a single canvas.
	// GET /api/v2/elitea_core/canvas/prompt_lib/{project_id}/{id}
	GetCanvas(context.Context, *GetCanvasRequest) (*GetCanvasResponse, error)
	// UpdateCanvas updates an existing canvas.
	// PUT /api/v2/elitea_core/canvas/prompt_lib/{project_id}/{canvas_uuid}
	UpdateCanvas(context.Context, *UpdateCanvasRequest) (*UpdateCanvasResponse, error)
	// GetContextStatus returns context-window analytics for a conversation.
	// GET /api/v2/elitea_core/context_analytics/prompt_lib/{project_id}/{conversation_id}
	GetContextStatus(context.Context, *GetContextStatusRequest) (*GetContextStatusResponse, error)
	// UpdateContextStrategy sets the context management strategy for a
	// conversation (e.g. summarise, truncate, sliding window).
	// PUT /api/v2/elitea_core/context_strategy/prompt_lib/{project_id}/{conversation_id}
	UpdateContextStrategy(context.Context, *UpdateContextStrategyRequest) (*UpdateContextStrategyResponse, error)
	// OptimizeContext triggers an immediate context optimisation pass.
	// POST /api/v2/context_manager/optimize_context/{project_id}/{conversation_id}
	OptimizeContext(context.Context, *OptimizeContextRequest) (*OptimizeContextResponse, error)
	// GetContextAnalytics returns token-budget utilisation analytics.
	// GET /api/v2/context_manager/analytics/{project_id}/{conversation_id}
	GetContextAnalytics(context.Context, *GetContextAnalyticsRequest) (*GetContextAnalyticsResponse, error)
	// GenerateSummary creates a new summary for a conversation.
	// POST /api/v2/context_manager/summaries/{project_id}/{conversation_id}
	GenerateSummary(context.Context, *GenerateSummaryRequest) (*GenerateSummaryResponse, error)
	// ListSummaries returns a paginated list of summaries for a conversation.
	// GET /api/v2/context_manager/summaries/{project_id}/{conversation_id}
	ListSummaries(context.Context, *ListSummariesRequest) (*ListSummariesResponse, error)
	// UpdateSummary updates the text or metadata of an existing summary.
	// PUT /api/v2/context_manager/summary/{project_id}/{conversation_id}/{summary_id}
	UpdateSummary(context.Context, *UpdateSummaryRequest) (*UpdateSummaryResponse, error)
	// DeleteSummary removes a summary from a conversation.
	// DELETE /api/v2/context_manager/summary/{project_id}/{conversation_id}/{summary_id}
	DeleteSummary(context.Context, *DeleteSummaryRequest) (*DeleteSummaryResponse, error)
	// SetAttachmentStorage configures the storage toolkit for a conversation.
	// PUT /api/v2/elitea_core/attachment_storage/prompt_lib/{project_id}/{conversation_id}
	SetAttachmentStorage(context.Context, *SetAttachmentStorageRequest) (*SetAttachmentStorageResponse, error)
	// UploadAttachments uploads files to a conversation.
	// The REST endpoint accepts multipart/form-data; the gRPC representation
	// uses repeated FileUpload messages carrying raw bytes.
	// POST /api/v2/elitea_core/attachments/prompt_lib/{project_id}/{conversation_id}
	UploadAttachments(context.Context, *UploadAttachmentsRequest) (*UploadAttachmentsResponse, error)
	// RemoveAttachments deletes one or all attachments from a conversation.
	// DELETE /api/v2/elitea_core/attachments/prompt_lib/{project_id}/{conversation_id}
	RemoveAttachments(context.Context, *RemoveAttachmentsRequest) (*RemoveAttachmentsResponse, error)
	// FolderCreate creates a new conversation folder.
	// POST /api/v2/elitea_core/folder/prompt_lib/{project_id}
	FolderCreate(context.Context, *FolderCreateRequest) (*FolderCreateResponse, error)
	// ListFolders covers three GET /folder/{project_id} call variants:
	//   - foldersList:             grouped=true, no folder_id/date_group
	//   - folderConversations:     grouped=true, folder_id set
	//   - dateGroupConversations:  grouped=true, date_group set
	//
	// The handler inspects which optional fields are present to select behaviour.
	// GET /api/v2/elitea_core/folder/prompt_lib/{project_id}
	ListFolders(context.Context, *ListFoldersRequest) (*ListFoldersResponse, error)
	// FolderUpdate updates a folder's name or other metadata.
	// PUT /api/v2/elitea_core/folder/prompt_lib/{project_id}/{id}
	FolderUpdate(context.Context, *FolderUpdateRequest) (*FolderUpdateResponse, error)
	// FolderPinUpdate toggles the pinned state of a folder.
	// PATCH /api/v2/elitea_core/folder/prompt_lib/{project_id}/{id}
	FolderPinUpdate(context.Context, *FolderPinUpdateRequest) (*FolderPinUpdateResponse, error)
	// DeleteFolder permanently removes a folder.
	// DELETE /api/v2/elitea_core/folder/prompt_lib/{project_id}/{id}
	DeleteFolder(context.Context, *DeleteFolderRequest) (*DeleteFolderResponse, error)
	mustEmbedUnimplementedChatServiceServer()
}

